// Fontes gratuitas do radar ViceScope.
// O RSS entrega apenas descoberta. A verificacao do conteudo acontece no Fluxo 02.
return [
  {
    json: {
      sourceName: 'Rockstar Games - YouTube oficial',
      sourceType: 'official',
      url: 'https://www.youtube.com/feeds/videos.xml?channel_id=UC6VcWc1rAoWdBCM0JxrRQ3A'
    }
  },
  {
    json: {
      sourceName: 'Rockstar Newswire via Google News',
      sourceType: 'official_discovery',
      url: 'https://news.google.com/rss/search?q=site%3Arockstargames.com%2Fnewswire+%22Grand+Theft+Auto+VI%22+when%3A3d&hl=en-US&gl=US&ceid=US%3Aen'
    }
  },
  {
    json: {
      sourceName: 'Tendencias GTA VI - ultimos 2 dias',
      sourceType: 'news_discovery',
      url: 'https://news.google.com/rss/search?q=%28%22GTA+VI%22+OR+%22GTA+6%22+OR+%22Grand+Theft+Auto+VI%22%29+when%3A2d&hl=en-US&gl=US&ceid=US%3Aen'
    }
  }
];

// ViceScope Radar - versao auditada.
// Faz descoberta e triagem. Nao transforma titulo de RSS em fato confirmado.
const inputItems = $input.all();
const memory = $getWorkflowStaticData('global');
const now = Date.now();
const historyTtl = 14 * 24 * 60 * 60 * 1000;
const articleTtl = 3 * 24 * 60 * 60 * 1000;
const maxCandidates = 6;

const feedErrorCount = inputItems.filter(item =>
  Boolean(item.error || item.json?.error)
).length;

memory.seen = memory.seen || {};
for (const [key, timestamp] of Object.entries(memory.seen)) {
  if (!timestamp || now - timestamp > historyTtl) delete memory.seen[key];
}

const clean = (value = '') =>
  String(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const normalizeText = (value = '') =>
  clean(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

const normalizeUrl = (value = '') => {
  try {
    const url = new URL(value);
    for (const key of [...url.searchParams.keys()]) {
      if (key.startsWith('utm_') || ['gclid', 'fbclid', 'si'].includes(key)) {
        url.searchParams.delete(key);
      }
    }
    url.hash = '';
    return url.toString();
  } catch {
    return String(value).trim();
  }
};

const splitHeadlineAndPublisher = (rawTitle = '') => {
  const title = clean(rawTitle);
  const separators = [...title.matchAll(/\s[-–—]\s/g)];

  if (separators.length === 0) {
    return { headline: title, suffixPublisher: '' };
  }

  const last = separators[separators.length - 1];
  const suffixPublisher = clean(title.slice(last.index + last[0].length));
  const headline = clean(title.slice(0, last.index));

  if (suffixPublisher.length < 2 || suffixPublisher.length > 100) {
    return { headline: title, suffixPublisher: '' };
  }

  return { headline, suffixPublisher };
};

const extractPublisher = (suffixPublisher, author, description) => {
  const knownAuthor = clean(author);
  if (knownAuthor && !/google news|fonte externa|unknown/i.test(knownAuthor)) {
    return knownAuthor;
  }

  if (suffixPublisher) return suffixPublisher;
  if (/rockstar games\s*$/i.test(description)) return 'Rockstar Games';
  return 'Fonte externa';
};

const getTopic = (text) => {
  const rules = [
    ['official-update', ['rockstar confirms', 'rockstar reveals', 'official announcement', 'newswire']],
    ['trailer', ['trailer']],
    ['leak', ['leak', 'leaked', 'leaker', 'cyberleek']],
    ['release', ['release date', 'launch date', 'delay', 'delayed', 'launch']],
    ['gameplay', ['gameplay', 'gameplay footage']],
    ['preorder', ['pre-order', 'preorder']],
    ['map', ['map', 'vice city']],
    ['characters', ['lucia', 'jason', 'character']],
    ['music-radio', ['soundtrack', 'radio station', 'music']],
    ['rating', ['rating', 'classification', 'esrb', 'pegi']],
    ['platforms', ['switch 2', 'pc version', 'xbox', 'playstation']],
    ['technology', ['ray tracing', 'performance', 'fps', 'graphics']],
    ['marketing', ['billboard', 'advertising', 'ads', 'marketing']],
    ['collectors', ['collector', 'collection', 'merchandise']]
  ];

  for (const [topic, terms] of rules) {
    if (terms.some(term => text.includes(term))) return topic;
  }
  return 'general';
};

const stableId = (value = '') => {
  let hash = 2166136261;
  for (const character of value) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return `gta6-${(hash >>> 0).toString(16).padStart(8, '0')}`;
};

const gtaPattern = /\b(gta\s*(vi|6)|grand theft auto\s*(vi|6))\b/i;
const officialPattern = /rockstar games|rockstargames\.com|rockstar newswire/i;

const strongTerms = [
  'trailer', 'gameplay', 'release date', 'delay', 'official',
  'rockstar confirms', 'rockstar reveals', 'announcement',
  'map', 'lucia', 'jason', 'vice city'
];

const rumorTerms = [
  'rumor', 'leak', 'leaked', 'leaker', 'allegedly', 'reportedly',
  'insider claims', 'might', 'could be', 'supposedly'
];

const junkTerms = [
  'earbuds', 'headphones', 'best price', 'deal compared',
  'cheapest', 'stock rebounds', 'shares', 'investor',
  'skyrim gets', 'take time off', 'leave on the gta',
  'holiday request', 'buy now'
];

const brandRiskPatterns = [
  /\bnude\b/,
  /\bnudity\b/,
  /\bnaked\b/,
  /\bnsfw\b/,
  /\bsex\b/,
  /\bsexual\b/,
  /\bsexually\b/,
  /\bporn\b/,
  /\bpornographic\b/,
  /\btopless\b/,
  /\buncensored\b/,
  /\bexplicit content\b/
];

const trustedPublishers = [
  'ign', 'gamespot', 'eurogamer', 'polygon', 'the verge',
  'rock paper shotgun', 'pc gamer', 'kotaku', 'vgc',
  'game informer', 'playstation', 'xbox'
];

const candidates = [];

for (const item of inputItems) {
  const data = item.json || {};
  const rawTitle = clean(data.title);
  const { headline, suffixPublisher } = splitHeadlineAndPublisher(rawTitle);
  const description = clean(
    data.contentSnippet || data.content || data.summary || data.description
  );
  const url = normalizeUrl(data.link || data.guid || data.url);
  const author = clean(data.creator || data.author || data['dc:creator']);
  const publisher = extractPublisher(suffixPublisher, author, description);
  const text = normalizeText(`${headline} ${description}`);
  const publisherText = normalizeText(publisher);

  if (!headline || !url || !gtaPattern.test(text)) continue;
  if (junkTerms.some(term => text.includes(term))) continue;
  if (brandRiskPatterns.some(pattern => pattern.test(text))) continue;

  const publishedRaw = data.isoDate || data.pubDate || data.published || data.date;
  const parsedPublished = publishedRaw ? new Date(publishedRaw).getTime() : now;
  const publishedMs = Number.isFinite(parsedPublished) ? parsedPublished : now;
  const dateAnomaly = publishedMs > now + (6 * 60 * 60 * 1000);
  if (now - publishedMs > articleTtl) continue;

  const key = url.toLowerCase().replace(/\/$/, '');
  if (memory.seen[key]) continue;

  const googleNewsRedirect = /news\.google\.com/i.test(url);
  const officialRockstar =
    officialPattern.test(publisherText) ||
    officialPattern.test(author) ||
    (!googleNewsRedirect && /rockstargames\.com/i.test(url));

  const trusted = trustedPublishers.some(source =>
    publisherText === source ||
    publisherText.startsWith(`${source}.`) ||
    publisherText.startsWith(`${source} `)
  );

  const rumorHits = rumorTerms.filter(term => text.includes(term));
  const strongHits = strongTerms.filter(term => text.includes(term));
  const effectivePublishedMs = Math.min(publishedMs, now);
  const ageHours = Math.max(0, (now - effectivePublishedMs) / 3600000);

  let score = officialRockstar ? 100 : trusted ? 72 : 55;
  score += strongHits.length * 4;
  score -= rumorHits.length * 8;
  score += ageHours <= 6 ? 8 : ageHours <= 24 ? 4 : 0;
  score = Math.max(0, Math.min(100, score));

  const topic = getTopic(text);
  const riskFlags = [];
  if (googleNewsRedirect) riskFlags.push('resolve_google_news_url');
  if (rumorHits.length) riskFlags.push('unconfirmed_claim');
  if (dateAnomaly) riskFlags.push('future_date_anomaly');
  if (!officialRockstar && !trusted) riskFlags.push('unknown_source');

  candidates.push({
    candidateId: stableId(key),
    radarEmpty: false,
    title: headline,
    sourceTitle: rawTitle,
    discoveryUrl: url,
    publisher,
    publishedAt: new Date(publishedMs).toISOString(),
    snippet: description.slice(0, 650),
    topic,
    official: officialRockstar,
    sourceTier: officialRockstar ? 'official' : trusted ? 'trusted_press' : 'unknown',
    reliability: officialRockstar
      ? 'official_source_discovered'
      : trusted
        ? 'trusted_press_needs_confirmation'
        : 'needs_verification',
    verificationRequired:
      !officialRockstar || googleNewsRedirect || rumorHits.length > 0 || dateAnomaly,
    urlResolutionRequired: googleNewsRedirect,
    riskFlags,
    viralScore: score,
    _key: key
  });
}

candidates.sort((a, b) =>
  Number(b.official) - Number(a.official) ||
  b.viralScore - a.viralScore ||
  new Date(b.publishedAt) - new Date(a.publishedAt)
);

const selected = [];
const usedTopics = new Set();
const usedExternalPublishers = new Set();

for (const candidate of candidates) {
  const publisherKey = normalizeText(candidate.publisher);

  if (usedTopics.has(candidate.topic)) continue;
  if (!candidate.official && usedExternalPublishers.has(publisherKey)) continue;

  usedTopics.add(candidate.topic);
  if (!candidate.official) usedExternalPublishers.add(publisherKey);
  selected.push(candidate);

  if (selected.length >= maxCandidates) break;
}

const diagnostics = {
  rawItemCount: inputItems.length,
  feedErrorCount,
  partialFeedFailure: feedErrorCount > 0,
  qualifiedBeforeDiversity: candidates.length,
  selectedCount: selected.length
};

if (selected.length === 0) {
  return [{
    json: {
      radarEmpty: true,
      radarStatus: feedErrorCount > 0 ? 'source_error' : 'empty',
      status: feedErrorCount > 0
        ? 'Uma ou mais fontes falharam e nenhuma pauta qualificada foi encontrada.'
        : 'Nenhuma pauta nova e qualificada sobre GTA VI nesta execucao.',
      diagnostics
    }
  }];
}

// Marca todo o lote qualificado como avaliado. Assim, a proxima execucao
// nao despeja pautas inferiores que perderam a selecao deste ciclo.
for (const candidate of candidates) {
  memory.seen[candidate._key] = now;
}

return selected.map(candidate => {
  delete candidate._key;
  return { json: { ...candidate, diagnostics } };
});

const input = $input.all();

if (input.length === 1 && input[0].json.radarEmpty) {
  const first = input[0].json;
  return [{
    json: {
      schemaVersion: '1.0',
      status: first.radarStatus || 'empty',
      generatedAt: new Date().toISOString(),
      count: 0,
      officialCount: 0,
      requiresVerificationCount: 0,
      candidates: [],
      diagnostics: first.diagnostics || {},
      message: first.status
    }
  }];
}

const candidates = input
  .map(item => item.json)
  .filter(item => !item.radarEmpty)
  .map(({ diagnostics, ...candidate }) => candidate)
  .sort((a, b) =>
    Number(b.official) - Number(a.official) ||
    b.viralScore - a.viralScore
  );

return [{
  json: {
    schemaVersion: '1.0',
    status: 'ready_for_editorial_ai',
    generatedAt: new Date().toISOString(),
    count: candidates.length,
    officialCount: candidates.filter(item => item.official).length,
    requiresVerificationCount: candidates.filter(item => item.verificationRequired).length,
    diagnostics: input[0]?.json?.diagnostics || {},
    editorialRules: {
      doNotInventFacts: true,
      externalClaimsNeedConfirmation: true,
      resolveDiscoveryUrlsBeforeWriting: true,
      preferOfficialSources: true,
      narrationLanguage: 'en-US',
      approvalSummaryLanguage: 'pt-BR',
      noAutomaticPublishing: true
    },
    renderContract: {
      workflowFile: 'render.yml',
      narrationMaxCharacters: 1200,
      titleMaxCharacters: 50,
      subtitleMaxCharacters: 70,
      allowedVoices: ['am_adam', 'am_michael', 'af_heart', 'af_bella'],
      defaultVoice: 'am_adam',
      allowedSpeeds: ['0.95', '1.00', '1.08', '1.15'],
      defaultSpeed: '1.08'
    },
    candidates
  }
}];
